// GENERATED by `bun scripts/env-gen.ts` from the registry in shared/env/ — edit the registry, not this file.
//
// The renderer image is built from renderer/ alone, so it cannot import
// shared/env. This file carries a copy of shared/env/coerce.ts (exports
// dropped: only the loader below is the module's API) and
// the renderer's slice of the registry; tests/unit/env/generated.test.ts
// checks that it parses exactly like loadEnv('renderer').

/* eslint-disable */
class EnvValueError extends Error {}

interface Coercer<T> {
  /** Short type label for the generated reference (`boolean`, `integer ≥ 0`, …). */
  readonly label: string
  /** TypeScript type of the parsed value (for generated code). */
  readonly tsType: string
  /** Expression that rebuilds this coercer from this file's exports (for generated code). */
  readonly expr: string
  /** Parse a trimmed, non-empty raw value; throws `EnvValueError`. */
  parse(raw: string): T
}

function fail(expected: string): never {
  throw new EnvValueError(`expected ${expected}`)
}

const TRUE_WORDS = new Set(['1', 'true', 'yes', 'on'])
const FALSE_WORDS = new Set(['0', 'false', 'no', 'off'])

/** One boolean dialect for every flag: 1/true/yes/on and 0/false/no/off, any case. */
const bool: Coercer<boolean> = {
  label: 'boolean',
  tsType: 'boolean',
  expr: 'bool',
  parse(raw) {
    const v = raw.toLowerCase()
    if (TRUE_WORDS.has(v)) return true
    if (FALSE_WORDS.has(v)) return false
    return fail('a boolean (true/false, 1/0, yes/no, on/off)')
  }
}

/** Free text. */
const string: Coercer<string> = {
  label: 'string',
  tsType: 'string',
  expr: 'string',
  parse: raw => raw
}

interface RangeOptions {
  min?: number
  max?: number
}

function rangeLabel(base: string, opts: RangeOptions): string {
  if (opts.min !== undefined && opts.max !== undefined) return `${base} ${opts.min}–${opts.max}`
  if (opts.min !== undefined) return `${base} ≥ ${opts.min}`
  if (opts.max !== undefined) return `${base} ≤ ${opts.max}`
  return base
}

function checkRange(n: number, label: string, opts: RangeOptions): number {
  if (opts.min !== undefined && n < opts.min) fail(label)
  if (opts.max !== undefined && n > opts.max) fail(label)
  return n
}

/** A whole number (decimal digits, optional leading minus). */
function int(opts: RangeOptions = {}): Coercer<number> {
  const label = rangeLabel('integer', opts)
  return {
    label,
    tsType: 'number',
    expr: `int(${JSON.stringify(opts)})`,
    parse(raw) {
      if (!/^-?\d+$/.test(raw)) fail(`an ${label}`)
      const n = Number(raw)
      if (!Number.isSafeInteger(n)) fail(`an ${label}`)
      return checkRange(n, `an ${label}`, opts)
    }
  }
}

/** An integer ≥ 1. */
const positiveInt: Coercer<number> = { ...int({ min: 1 }), expr: 'positiveInt' }

/** An integer ≥ 0. */
const nonNegativeInt: Coercer<number> = { ...int({ min: 0 }), expr: 'nonNegativeInt' }

/** A TCP port. */
const port: Coercer<number> = { ...int({ min: 1, max: 65535 }), expr: 'port' }

/** A finite decimal number. */
function number(opts: RangeOptions = {}): Coercer<number> {
  const label = rangeLabel('number', opts)
  return {
    label,
    tsType: 'number',
    expr: `number(${JSON.stringify(opts)})`,
    parse(raw) {
      if (!/^-?(\d+\.?\d*|\.\d+)$/.test(raw)) fail(`a ${label}`)
      return checkRange(Number(raw), `a ${label}`, opts)
    }
  }
}

/** A finite number > 0 (prices, budgets, plan caps). */
const positiveNumber: Coercer<number> = {
  label: 'number > 0',
  tsType: 'number',
  expr: 'positiveNumber',
  parse(raw) {
    if (!/^(\d+\.?\d*|\.\d+)$/.test(raw)) fail('a number > 0')
    const n = Number(raw)
    if (n <= 0) fail('a number > 0')
    return n
  }
}

/** `base` under another label, which its error message uses too. */
function relabel<T>(base: Coercer<T>, label: string, expr: string): Coercer<T> {
  return {
    label,
    tsType: base.tsType,
    expr,
    parse(raw) {
      try {
        return base.parse(raw)
      } catch (e) {
        if (e instanceof EnvValueError) fail(label)
        throw e
      }
    }
  }
}

/** A byte count (integer ≥ 1). Plain digits: `16777216`, not `16MiB`. */
const bytes: Coercer<number> = relabel(int({ min: 1 }), 'bytes (integer ≥ 1)', 'bytes')

/** A duration in milliseconds (integer ≥ 1). */
const durationMs: Coercer<number> = relabel(int({ min: 1 }), 'milliseconds (integer ≥ 1)', 'durationMs')

/** An absolute URL with one of the given schemes; returned as written (trimmed). */
function url(schemes: readonly string[] = ['http', 'https']): Coercer<string> {
  const label = `${schemes.join('/')} URL`
  return {
    label,
    tsType: 'string',
    expr: `url(${JSON.stringify(schemes)})`,
    parse(raw) {
      let parsed: URL
      try {
        parsed = new URL(raw)
      } catch {
        return fail(`an absolute ${label}`)
      }
      if (!schemes.includes(parsed.protocol.slice(0, -1))) fail(`an absolute ${label}`)
      return raw
    }
  }
}

const HOSTNAME = /^(?=.{1,253}$)[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*\.?$/i

/** A DNS hostname (letters, digits, '-', '.'); no scheme, no port. */
const hostname: Coercer<string> = {
  label: 'hostname',
  tsType: 'string',
  expr: 'hostname',
  parse(raw) {
    if (!HOSTNAME.test(raw)) fail('a hostname (letters, digits, "-" and "." only)')
    return raw
  }
}

const EMAIL = /^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]+$/

/** An email address. */
const email: Coercer<string> = {
  label: 'email address',
  tsType: 'string',
  expr: 'email',
  parse(raw) {
    if (raw.length > 254 || !EMAIL.test(raw)) fail('an email address')
    return raw
  }
}

/** Text matching `re`; `expected` describes it in the error. */
function pattern(re: RegExp, expected: string): Coercer<string> {
  return {
    label: expected,
    tsType: 'string',
    expr: `pattern(${re.toString()}, ${JSON.stringify(expected)})`,
    parse(raw) {
      if (!re.test(raw)) fail(expected)
      return raw
    }
  }
}

/** Comma-separated list; entries trimmed, empty entries dropped. */
function csv<T = string>(item?: Coercer<T>): Coercer<T[]> {
  return {
    label: item ? `comma-separated ${item.label} list` : 'comma-separated list',
    tsType: `${item ? item.tsType : 'string'}[]`,
    expr: `csv(${item ? item.expr : ''})`,
    parse(raw) {
      const entries = raw.split(',').map(s => s.trim()).filter(Boolean)
      if (!item) return entries as T[]
      return entries.map((entry, i) => {
        try {
          return item.parse(entry)
        } catch (e) {
          if (e instanceof EnvValueError) throw new EnvValueError(`entry ${i + 1}: ${e.message}`)
          throw e
        }
      })
    }
  }
}

/** One of a fixed set of words (case-insensitive; returned lowercase). */
function oneOf<const T extends string>(values: readonly T[]): Coercer<T> {
  return {
    label: values.join(' | '),
    tsType: values.map(v => JSON.stringify(v)).join(' | '),
    expr: `oneOf(${JSON.stringify(values)})`,
    parse(raw) {
      const v = raw.toLowerCase()
      const hit = values.find(x => x === v)
      if (hit === undefined) fail(`one of ${values.join(', ')}`)
      return hit
    }
  }
}

/** A secret of at least `minLength` characters. */
function secret(minLength = 1): Coercer<string> {
  return {
    label: minLength > 1 ? `secret, ≥ ${minLength} chars` : 'secret',
    tsType: 'string',
    expr: `secret(${minLength})`,
    parse(raw) {
      if (raw.length < minLength) fail(`at least ${minLength} characters (got ${raw.length})`)
      return raw
    }
  }
}

/** A positive number, or the word `unlimited` (→ null). */
function limitOrUnlimited(base: Coercer<number>): Coercer<number | null> {
  return {
    label: `${base.label}, or unlimited`,
    tsType: `${base.tsType} | null`,
    expr: `limitOrUnlimited(${base.expr})`,
    parse(raw) {
      if (raw.toLowerCase() === 'unlimited') return null
      try {
        return base.parse(raw)
      } catch (e) {
        if (e instanceof EnvValueError) fail(`a ${base.label} or "unlimited"`)
        throw e
      }
    }
  }
}

interface Spec {
  group: string
  key: string
  name: string
  type: Coercer<unknown>
  default?: unknown
  required?: 'always' | 'production'
  emptyIsValue?: boolean
}

const SPECS: readonly Spec[] = [
  { group: "core", key: "nodeEnv", name: "NODE_ENV", type: string },
  { group: "auth", key: "internalApiSecret", name: "INTERNAL_API_SECRET", type: secret(32), required: "always" },
  { group: "auth", key: "internalApiSecretPrevious", name: "INTERNAL_API_SECRET_PREVIOUS", type: secret(32) },
  { group: "storage", key: "endpoint", name: "S3_ENDPOINT", type: url(["http","https"]), required: "always" },
  { group: "storage", key: "publicEndpoint", name: "S3_PUBLIC_ENDPOINT", type: url(["http","https"]) },
  { group: "storage", key: "accessKey", name: "S3_ACCESS_KEY", type: string, required: "always" },
  { group: "storage", key: "secretKey", name: "S3_SECRET_KEY", type: string, required: "always" },
  { group: "storage", key: "bucket", name: "S3_BUCKET", type: string, default: "ypad" },
  { group: "storage", key: "sse", name: "S3_SSE", type: string, default: "AES256", emptyIsValue: true },
  { group: "renderer", key: "allowedOrigins", name: "RENDERER_ALLOWED_ORIGINS", type: csv(url(["http","https"])), default: [] },
  { group: "renderer", key: "port", name: "PORT", type: port, default: 9000 },
  { group: "renderer", key: "appUrl", name: "APP_URL", type: url(["http","https"]), default: "http://app:3000" },
  { group: "renderer", key: "chromiumSandbox", name: "RENDERER_CHROMIUM_SANDBOX", type: bool, default: true },
  { group: "renderer", key: "localhostTarget", name: "RENDERER_LOCALHOST_TARGET", type: hostname, default: "host.docker.internal" },
  { group: "observability", key: "dsn", name: "SENTRY_DSN", type: url(["http","https"]) }
]

export interface RendererEnv {
  readonly core: {
    readonly nodeEnv: string | undefined
  }
  readonly auth: {
    readonly internalApiSecret: string
    readonly internalApiSecretPrevious: string | undefined
  }
  readonly storage: {
    readonly endpoint: string
    readonly publicEndpoint: string | undefined
    readonly accessKey: string
    readonly secretKey: string
    readonly bucket: string
    readonly sse: string
  }
  readonly renderer: {
    readonly allowedOrigins: string[]
    readonly port: number
    readonly appUrl: string
    readonly chromiumSandbox: boolean
    readonly localhostTarget: string
  }
  readonly observability: {
    readonly dsn: string | undefined
  }
}

/** Parse and validate the renderer's environment; throws with every problem listed. */
export function loadRendererEnv(source: Record<string, string | undefined> = process.env): RendererEnv {
  const problems: string[] = []
  const out: Record<string, Record<string, unknown>> = {}
  for (const spec of SPECS) {
    const raw = source[spec.name]?.trim()
    let value: unknown = spec.default
    if (raw === '' && spec.emptyIsValue) {
      value = ''
    } else if (!raw) {
      if (spec.required === 'always' || (spec.required === 'production' && source.NODE_ENV === 'production')) {
        problems.push(`${spec.name}: required, not set`)
      }
    } else {
      try {
        value = spec.type.parse(raw)
      } catch (e) {
        if (!(e instanceof EnvValueError)) throw e
        problems.push(`${spec.name}: ${e.message}`)
      }
    }
    ;(out[spec.group] ??= {})[spec.key] = value
  }
  if (problems.length > 0) {
    throw new Error(`Invalid configuration of the renderer (${problems.length === 1 ? '1 problem' : `${problems.length} problems`}):\n`
      + problems.map(p => `  - ${p}`).join('\n')
      + '\nEvery variable is described in docs/reference/configuration.md.')
  }
  return out as unknown as RendererEnv
}
